import{_ as t,o as e,c as n,a3 as s}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"数据、状态与存储架构","description":"从数据责任、一致性、恢复、访问模式和隔离要求出发，选择 Agent 系统的存储拓扑并定义跨存储数据流。","frontmatter":{"title":"数据、状态与存储架构","description":"从数据责任、一致性、恢复、访问模式和隔离要求出发，选择 Agent 系统的存储拓扑并定义跨存储数据流。","verified_at":"2026-08-03","source":["https://docs.langchain.com/oss/python/langgraph/persistence","https://www.postgresql.org/docs/current/transaction-iso.html","https://redis.io/docs/latest/develop/use/","https://opentelemetry.io/docs/concepts/"],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"py-agent/architecture/system-architecture/data-state-storage-architecture.md","filePath":"py-agent/architecture/system-architecture/data-state-storage-architecture.md","lastUpdated":1786083160000}'),r={name:"py-agent/architecture/system-architecture/data-state-storage-architecture.md"};function d(l,a,i,p,o,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="数据、状态与存储架构" tabindex="-1">数据、状态与存储架构 <a class="header-anchor" href="#数据、状态与存储架构" aria-label="Permalink to &quot;数据、状态与存储架构&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent 系统会同时产生业务记录、任务状态、工作流 Checkpoint、长期记忆、文档索引、缓存和 Trace。架构问题不是把这些名词分别对应到某种数据库，而是确定：哪些事实必须原子提交，哪些数据允许异步派生，故障后以谁为准，以及系统需要为哪些读取和恢复路径付出复杂度。</p><p>本文讨论系统级存储拓扑和数据流决策。各类数据的字段、所有权和应用实现由 <a href="/py-agent/application/data-persistence/data-architecture-state-ownership">数据架构与状态所有权</a> 展开；PostgreSQL、Redis、Checkpointer 和向量数据库的具体 API 不在本文重复讲解。</p><h2 id="_1-决策边界" tabindex="-1">1. 决策边界 <a class="header-anchor" href="#_1-决策边界" aria-label="Permalink to &quot;1. 决策边界&quot;">​</a></h2><h3 id="_1-1-本文要决定什么" tabindex="-1">1.1 本文要决定什么 <a class="header-anchor" href="#_1-1-本文要决定什么" aria-label="Permalink to &quot;1.1 本文要决定什么&quot;">​</a></h3><p>一项数据架构决策至少需要回答：</p><ul><li>系统对外承诺的事实保存在哪里；</li><li>一次 Agent 执行从哪里恢复；</li><li>文档、记忆、缓存和遥测如何从权威数据派生；</li><li>哪些写入必须位于同一事务，哪些只能最终一致；</li><li>单个存储、组合存储或隔离 Cell 哪一种满足当前约束；</li><li>数据丢失、陈旧、重复和版本不兼容时怎样恢复。</li></ul><h3 id="_1-2-本文不决定什么" tabindex="-1">1.2 本文不决定什么 <a class="header-anchor" href="#_1-2-本文不决定什么" aria-label="Permalink to &quot;1.2 本文不决定什么&quot;">​</a></h3><p>本文不替代表结构设计、ORM 教程、Redis 命令、向量检索原理或 LangGraph 持久化 API。架构先定义责任和保证，实现文章再把这些保证映射到产品与代码。</p><h2 id="_2-架构驱动因素" tabindex="-1">2. 架构驱动因素 <a class="header-anchor" href="#_2-架构驱动因素" aria-label="Permalink to &quot;2. 架构驱动因素&quot;">​</a></h2><h3 id="_2-1-权威性与一致性" tabindex="-1">2.1 权威性与一致性 <a class="header-anchor" href="#_2-1-权威性与一致性" aria-label="Permalink to &quot;2.1 权威性与一致性&quot;">​</a></h3><p>先判断一条数据是否代表用户承诺或业务事实。订单、审批结果、任务终态和幂等记录通常要求事务约束；Embedding、缓存和搜索索引通常允许从权威数据重建。权威数据越分散，跨系统冲突和恢复就越困难。</p><h3 id="_2-2-恢复与耐久性" tabindex="-1">2.2 恢复与耐久性 <a class="header-anchor" href="#_2-2-恢复与耐久性" aria-label="Permalink to &quot;2.2 恢复与耐久性&quot;">​</a></h3><p>需要区分三种恢复：业务记录恢复、任务调度恢复和工作流执行恢复。数据库备份可以恢复业务记录，队列租约可以重新投递任务，Checkpoint 可以恢复图的执行位置；三者不能互相替代。</p><h3 id="_2-3-访问模式与规模" tabindex="-1">2.3 访问模式与规模 <a class="header-anchor" href="#_2-3-访问模式与规模" aria-label="Permalink to &quot;2.3 访问模式与规模&quot;">​</a></h3><p>事务更新、按租户分页、向量相似检索、短期计数和海量 Trace 具有不同访问模式。应以真实的读写比例、数据量、峰值、尾延迟和保留期选择拓扑，而不是因为某个产品支持多种数据类型就把所有责任交给它。</p><h3 id="_2-4-隔离与生命周期" tabindex="-1">2.4 隔离与生命周期 <a class="header-anchor" href="#_2-4-隔离与生命周期" aria-label="Permalink to &quot;2.4 隔离与生命周期&quot;">​</a></h3><p>租户、地域、敏感等级、保留、删除和审计要求会改变存储边界。例如境内数据可能不能复制到境外模型或观测平台；用户删除请求还需要传播到记忆、索引、缓存和可定位的遥测副本。</p><h3 id="_2-5-团队与运行能力" tabindex="-1">2.5 团队与运行能力 <a class="header-anchor" href="#_2-5-团队与运行能力" aria-label="Permalink to &quot;2.5 团队与运行能力&quot;">​</a></h3><p>每增加一个存储系统，就增加备份、迁移、监控、权限、容量和值班责任。如果团队无法独立验证和恢复该系统，专用存储的性能优势可能不足以抵消运行风险。</p><h2 id="_3-数据责任地图" tabindex="-1">3. 数据责任地图 <a class="header-anchor" href="#_3-数据责任地图" aria-label="Permalink to &quot;3. 数据责任地图&quot;">​</a></h2><p>架构设计需要先建立责任地图，再讨论产品：</p><table tabindex="0"><thead><tr><th>数据责任</th><th>回答的问题</th><th>典型权威位置</th><th>是否可重建</th></tr></thead><tbody><tr><td>业务事实</td><td>用户和业务系统承诺了什么</td><td>事务数据库或权威业务系统</td><td>通常不可</td></tr><tr><td>任务记录</td><td>应用接受了什么工作、终态是什么</td><td>事务数据库</td><td>通常不可</td></tr><tr><td>Agent State</td><td>本次执行当前知道什么</td><td>运行时 State</td><td>取决于 Checkpoint</td></tr><tr><td>Checkpoint</td><td>从哪个执行边界恢复</td><td>Checkpointer</td><td>部分可重算，但可能昂贵或有副作用</td></tr><tr><td>长期记忆</td><td>跨运行保留什么信息</td><td>受治理 Store 或业务数据库</td><td>取决于来源</td></tr><tr><td>文档与索引</td><td>能检索哪些来源及其派生表示</td><td>文档源 + 派生索引</td><td>索引可重建</td></tr><tr><td>缓存</td><td>哪些结果允许短期复用</td><td>Redis 或本地缓存</td><td>应当可重建</td></tr><tr><td>事件与 Outbox</td><td>哪些已提交事实尚待发布</td><td>事务数据库</td><td>不应依赖内存重建</td></tr><tr><td>Trace 与日志</td><td>一次运行发生了什么</td><td>观测后端</td><td>不是业务恢复来源</td></tr></tbody></table><p>同一种数据库可以承载多项责任，但责任之间仍要有独立 Schema、权限和生命周期。相反，使用多个产品也不代表责任已经清楚；如果两个系统都能独立修改同一事实，系统仍然没有权威答案。</p><h2 id="_4-一致性边界" tabindex="-1">4. 一致性边界 <a class="header-anchor" href="#_4-一致性边界" aria-label="Permalink to &quot;4. 一致性边界&quot;">​</a></h2><h3 id="_4-1-单一事务内的不变量" tabindex="-1">4.1 单一事务内的不变量 <a class="header-anchor" href="#_4-1-单一事务内的不变量" aria-label="Permalink to &quot;4.1 单一事务内的不变量&quot;">​</a></h3><p>会共同决定用户可见结果的数据，应尽量位于同一事务所有者内。例如创建 <code>run</code>、创建首个 <code>task</code> 和写入 Outbox 可以在一个 PostgreSQL 事务中完成。事务成功后，应用能够证明任务已经被接受且发布动作可恢复。</p><h3 id="_4-2-跨存储的数据流" tabindex="-1">4.2 跨存储的数据流 <a class="header-anchor" href="#_4-2-跨存储的数据流" aria-label="Permalink to &quot;4.2 跨存储的数据流&quot;">​</a></h3><p>业务数据库、Checkpointer、向量索引、Redis 和观测平台通常不存在一个全局事务。跨存储链路应明确：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>权威写入</span></span>
<span class="line"><span>  -&gt; 提交业务事务与 Outbox</span></span>
<span class="line"><span>  -&gt; 至少一次发布事件</span></span>
<span class="line"><span>  -&gt; 幂等更新索引、缓存或下游系统</span></span>
<span class="line"><span>  -&gt; 记录处理水位与失败</span></span>
<span class="line"><span>  -&gt; 对账并修复长期不一致</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Outbox 保证已提交事实可以继续发布，不保证所有下游同时成功；幂等防止重复处理产生重复结果，也不等同于全局 exactly-once。</p><h3 id="_4-3-最终一致的可见语义" tabindex="-1">4.3 最终一致的可见语义 <a class="header-anchor" href="#_4-3-最终一致的可见语义" aria-label="Permalink to &quot;4.3 最终一致的可见语义&quot;">​</a></h3><p>只写“最终一致”不够。每条派生链路还要定义最大陈旧时间、版本或水位、用户看到旧数据时的行为，以及超出阈值后的降级。例如知识库索引落后文档源 30 分钟时，可以显示数据水位、暂停高风险回答或回退到直接查询权威源。</p><h3 id="_4-4-删除传播" tabindex="-1">4.4 删除传播 <a class="header-anchor" href="#_4-4-删除传播" aria-label="Permalink to &quot;4.4 删除传播&quot;">​</a></h3><p>删除同样是一条数据流。权威源先记录删除或撤销，再清理 Checkpoint、记忆、索引、缓存、评测副本和可定位日志。备份中的保留例外需要说明恢复后如何再次应用删除，而不是宣称一次请求可以物理删除所有历史介质。</p><h2 id="_5-候选存储拓扑" tabindex="-1">5. 候选存储拓扑 <a class="header-anchor" href="#_5-候选存储拓扑" aria-label="Permalink to &quot;5. 候选存储拓扑&quot;">​</a></h2><h3 id="_5-1-关系数据库核心" tabindex="-1">5.1 关系数据库核心 <a class="header-anchor" href="#_5-1-关系数据库核心" aria-label="Permalink to &quot;5.1 关系数据库核心&quot;">​</a></h3><p>业务数据、任务、Outbox，甚至小规模 Checkpoint 和向量索引都放在同一个关系数据库中。它的优点是事务边界清楚、备份和权限集中、早期运行成本低；限制是高吞吐缓存、长时间 Trace 或大规模向量检索可能争用同一资源。</p><p>适合流量较小、团队规模有限、数据量可控且事务正确性优先的系统。不要因为未来可能扩展，就在第一版预先部署所有专用存储。</p><h3 id="_5-2-关系数据库加-redis" tabindex="-1">5.2 关系数据库加 Redis <a class="header-anchor" href="#_5-2-关系数据库加-redis" aria-label="Permalink to &quot;5.2 关系数据库加 Redis&quot;">​</a></h3><p>关系数据库继续保存权威事实，Redis 承担短期缓存、限流、租约和协调。该拓扑改善热点和瞬时并发，但必须保证 Redis 丢失或 Key 过期不会改变业务正确性。</p><p>适合存在明确热点、短期状态或协调需求的应用。若任务终态只保存在 Redis，这已经越过了缓存和协调的责任边界。</p><h3 id="_5-3-关系数据库加专用存储" tabindex="-1">5.3 关系数据库加专用存储 <a class="header-anchor" href="#_5-3-关系数据库加专用存储" aria-label="Permalink to &quot;5.3 关系数据库加专用存储&quot;">​</a></h3><p>在前一拓扑上增加对象存储、向量索引、独立 Checkpointer、消息 Broker 或观测后端。专用系统可以匹配访问模式并隔离负载，但需要版本、水位、重建、对账和独立恢复能力。</p><p>适合文档规模、检索负载、长任务或观测数据已经形成可测瓶颈的系统。每个新增系统都应对应一个已经出现或通过容量实验确认的驱动因素。</p><h3 id="_5-4-cell-与地域拓扑" tabindex="-1">5.4 Cell 与地域拓扑 <a class="header-anchor" href="#_5-4-cell-与地域拓扑" aria-label="Permalink to &quot;5.4 Cell 与地域拓扑&quot;">​</a></h3><p>按租户、地域或故障域把应用和数据划分为多个 Cell，每个 Cell 拥有自己的事务存储、缓存、队列和索引，共享控制面只分配配置和路由。该方式能限制故障和数据复制范围，但会增加租户迁移、全局统计、配置一致性和运维成本。</p><p>适合明确的数据地域、强隔离或大规模故障域要求。多租户隔离级别的选择在 <a href="/py-agent/architecture/system-architecture/multi-tenancy-architecture">多租户架构</a> 继续展开。</p><h2 id="_6-拓扑比较与选择" tabindex="-1">6. 拓扑比较与选择 <a class="header-anchor" href="#_6-拓扑比较与选择" aria-label="Permalink to &quot;6. 拓扑比较与选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>关系数据库核心</th><th>加 Redis</th><th>加专用存储</th><th>Cell / 地域化</th></tr></thead><tbody><tr><td>事务边界</td><td>最清楚</td><td>权威事务仍集中</td><td>需要跨系统数据流</td><td>Cell 内集中、全局分散</td></tr><tr><td>运行复杂度</td><td>最低</td><td>中</td><td>高</td><td>最高</td></tr><tr><td>热点与吞吐</td><td>中</td><td>强</td><td>按系统分别扩展</td><td>可按 Cell 扩展</td></tr><tr><td>检索与制品</td><td>能力有限或共享资源</td><td>基本不解决</td><td>最匹配专用负载</td><td>每个 Cell 独立治理</td></tr><tr><td>故障范围</td><td>单数据库影响大</td><td>多一个依赖</td><td>可隔离也可能级联</td><td>最易限制到 Cell</td></tr><tr><td>数据地域</td><td>依赖数据库部署</td><td>同左</td><td>每个存储都要合规</td><td>最容易形成地域边界</td></tr><tr><td>适用阶段</td><td>原型到中小规模</td><td>出现热点和协调需求</td><td>专用负载已被证明</td><td>隔离和规模成为核心约束</td></tr></tbody></table><p>选择时先淘汰不满足事务、地域、恢复和安全硬约束的候选，再比较延迟、成本与团队能力。不要把“组件更多”当成架构成熟度。</p><h2 id="_7-参考架构-售后执行-agent" tabindex="-1">7. 参考架构：售后执行 Agent <a class="header-anchor" href="#_7-参考架构-售后执行-agent" aria-label="Permalink to &quot;7. 参考架构：售后执行 Agent&quot;">​</a></h2><h3 id="_7-1-需求与选择" tabindex="-1">7.1 需求与选择 <a class="header-anchor" href="#_7-1-需求与选择" aria-label="Permalink to &quot;7.1 需求与选择&quot;">​</a></h3><p>假设系统需要保存用户会话、执行退款建议工作流、检索政策文档，并在人工确认后调用退款 API。关键约束是：退款不得重复、任务可跨进程恢复、知识索引可重建、首反馈低延迟。</p><p>选择如下：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PostgreSQL</span></span>
<span class="line"><span>  - tenant / user / thread / run / task</span></span>
<span class="line"><span>  - refund request / approval / operation id</span></span>
<span class="line"><span>  - outbox / audit reference</span></span>
<span class="line"><span></span></span>
<span class="line"><span>LangGraph Checkpointer</span></span>
<span class="line"><span>  - workflow state / interrupt / resume position</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Object Store + Vector Index</span></span>
<span class="line"><span>  - policy source / chunk / embedding / index version</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Redis</span></span>
<span class="line"><span>  - rate limit / short cache / worker coordination</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Observability Backend</span></span>
<span class="line"><span>  - trace / logs / metrics / token and cost</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>PostgreSQL 是业务承诺的权威源；Checkpoint 只证明执行到哪里；向量索引可以从政策原文重建；Redis 丢失最多降低性能或触发重新协调；Trace 用于解释运行，不负责恢复退款事实。</p><h3 id="_7-2-一次结果流" tabindex="-1">7.2 一次结果流 <a class="header-anchor" href="#_7-2-一次结果流" aria-label="Permalink to &quot;7.2 一次结果流&quot;">​</a></h3><ol><li>API 在 PostgreSQL 事务中创建 <code>run</code>、<code>task</code> 和 Outbox 记录。</li><li>Worker 领取任务并加载可信租户与用户上下文。</li><li>工作流在 Checkpoint 边界保存计划、政策引用和待审批动作。</li><li>检索只读取当前租户可见的索引版本，并返回源文档 ID。</li><li>人工批准后，退款工具使用稳定操作 ID 调用外部系统。</li><li>外部响应不明确时先按操作 ID 查询，不直接重复退款。</li><li>业务事务保存退款终态和新 Outbox；缓存与用户通知随后异步更新。</li></ol><h3 id="_7-3-故障时以谁为准" tabindex="-1">7.3 故障时以谁为准 <a class="header-anchor" href="#_7-3-故障时以谁为准" aria-label="Permalink to &quot;7.3 故障时以谁为准&quot;">​</a></h3><table tabindex="0"><thead><tr><th>故障</th><th>恢复依据</th><th>禁止做法</th></tr></thead><tbody><tr><td>Worker 崩溃</td><td>Task 租约、业务终态、Checkpoint</td><td>直接从头重复全部工具</td></tr><tr><td>Checkpointer 不可用</td><td>业务 Task 保持可恢复/失败状态</td><td>把业务状态改写成“已完成”</td></tr><tr><td>Redis 丢失</td><td>PostgreSQL 和上游重新填充</td><td>让任务或退款记录随缓存消失</td></tr><tr><td>索引损坏</td><td>原文、切分和 Embedding 版本重建</td><td>把现有向量当唯一原文</td></tr><tr><td>退款响应丢失</td><td>操作 ID 与外部权威 API 对账</td><td>无条件再次创建退款</td></tr><tr><td>Trace 采样缺失</td><td>业务审计与操作 ID</td><td>用模型生成解释补造证据</td></tr></tbody></table><h2 id="_8-恢复与容量设计" tabindex="-1">8. 恢复与容量设计 <a class="header-anchor" href="#_8-恢复与容量设计" aria-label="Permalink to &quot;8. 恢复与容量设计&quot;">​</a></h2><h3 id="_8-1-恢复目标" tabindex="-1">8.1 恢复目标 <a class="header-anchor" href="#_8-1-恢复目标" aria-label="Permalink to &quot;8.1 恢复目标&quot;">​</a></h3><p>分别为业务数据库、Checkpoint、索引、缓存和遥测定义 RPO 与 RTO：RPO 表示最多允许丢失多长时间的数据，RTO 表示故障后必须在多长时间内恢复。缓存可以允许全部丢失，业务退款记录通常不能；索引恢复时间可能较长，因此应保留可用旧版本或降级查询路径。</p><h3 id="_8-2-容量与保留" tabindex="-1">8.2 容量与保留 <a class="header-anchor" href="#_8-2-容量与保留" aria-label="Permalink to &quot;8.2 容量与保留&quot;">​</a></h3><p>估算增长时使用业务单位：每日 Run、每个 Run 的 Checkpoint 数、文档版本、Chunk 数、Trace Span、缓存 Key 和平均制品大小。只估数据库 GB 无法解释是哪类数据导致增长，也无法决定压缩、归档或重建策略。</p><h3 id="_8-3-故障隔离" tabindex="-1">8.3 故障隔离 <a class="header-anchor" href="#_8-3-故障隔离" aria-label="Permalink to &quot;8.3 故障隔离&quot;">​</a></h3><p>为模型、索引、缓存和外部 API 使用独立连接池、并发和 Deadline，避免一个慢依赖耗尽所有 Worker。共享数据库中的业务事务、向量查询和 Checkpoint 写入也要观察资源竞争，必要时再拆分，而不是默认它们永远互不影响。</p><h2 id="_9-决策记录" tabindex="-1">9. 决策记录 <a class="header-anchor" href="#_9-决策记录" aria-label="Permalink to &quot;9. 决策记录&quot;">​</a></h2><p>一份可复查的数据架构决策可以写成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>背景：售后 Agent 需要可恢复审批、政策检索和幂等退款</span></span>
<span class="line"><span>硬约束：退款事实不可丢失；境内数据；恢复不得重复副作用</span></span>
<span class="line"><span>候选：单 PostgreSQL；PostgreSQL + Redis；再增加对象存储和向量索引</span></span>
<span class="line"><span>选择：第三项，Checkpoint 第一阶段仍使用 PostgreSQL 后端</span></span>
<span class="line"><span>依据：政策文档 200 万 Chunk；缓存热点明确；团队可维护三类存储</span></span>
<span class="line"><span>权威源：业务与任务在 PostgreSQL，原文在对象存储</span></span>
<span class="line"><span>一致性：业务 + Outbox 同事务，索引和缓存至少一次异步更新</span></span>
<span class="line"><span>恢复：数据库 RPO 5 分钟；旧索引保留 7 天；Redis 可重建</span></span>
<span class="line"><span>负面后果：需要索引水位、删除传播和跨系统对账</span></span>
<span class="line"><span>复查：索引 p95 超标、Checkpoint 争用或新增地域要求</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>数字只展示决策结构，不是通用生产标准。</p><h2 id="_10-评审清单" tabindex="-1">10. 评审清单 <a class="header-anchor" href="#_10-评审清单" aria-label="Permalink to &quot;10. 评审清单&quot;">​</a></h2><ul><li>每类数据是否只有一个权威解释；</li><li>业务事务、任务恢复和工作流恢复是否明确区分；</li><li>新增存储是否对应已验证的访问模式或隔离要求；</li><li>跨存储写入是否定义 Outbox、幂等、水位和对账；</li><li>最终一致是否具有最大陈旧时间和用户可见语义；</li><li>删除是否传播到记忆、索引、缓存和观测副本；</li><li>每个存储是否有独立权限、容量、备份和恢复证据；</li><li>版本变化或规模增长时是否知道何时重新评估拓扑。</li></ul><p>数据架构的目标不是为每种数据寻找一个专用产品，而是建立可解释的责任和恢复链。先让业务事实、执行状态和派生数据各归其位，再以实际负载决定是否拆分存储，系统才不会用更多基础设施换来更多不一致。</p>`,76)])])}const u=t(r,[["render",d]]);export{b as __pageData,u as default};
